import { describe, expect, it } from 'vitest';
import { screenMapDiagram } from '../../../../src/domain/diagrams/screen-map.js';
import { cardOf, demoScreens, screenCard } from '../../../support/diagram-fixtures.js';

// RF-261, RF-508: the screen map, a flowchart generated by code from the "leads to" links.

const linesOf = (text: string): readonly string[] => text.trimEnd().split('\n');

describe('screenMapDiagram', () => {
  it('RF-261 draws the demo screens (snapshot)', () => {
    expect(screenMapDiagram(demoScreens())).toMatchSnapshot();
  });

  it('RF-261 one node per screen card in card id order, labelled with its route', () => {
    expect(linesOf(screenMapDiagram(demoScreens())).slice(0, 4)).toEqual([
      'flowchart LR',
      '  s1["#47;Basket.aspx"]',
      '  s2["#47;Checkout.aspx"]',
      '  s3["#47;Confirmation.aspx"]',
    ]);
  });

  it('RF-261 a link names a screen by card id or by route', () => {
    const lines = linesOf(screenMapDiagram(demoScreens()));

    expect(lines).toContain('  s1 --> s2');
    expect(lines).toContain('  s2 --> s3');
    expect(lines).toContain('  s2 --> s1');
  });

  it('RF-261 a link to a screen without a card gets its own node once', () => {
    const screens = [
      screenCard('SCRN-001', '/a', ['/missing', '/missing']),
      screenCard('SCRN-002', '/b', ['/missing']),
    ];
    const lines = linesOf(screenMapDiagram(screens));

    expect(lines.filter((line) => line.includes('#47;missing'))).toEqual(['  s3["#47;missing"]']);
    expect(lines.slice(-2)).toEqual(['  s1 --> s3', '  s2 --> s3']);
  });
});

describe('screenMapDiagram edge cases', () => {
  it('RF-261 a screen card without its detail is labelled with its title', () => {
    const bare = cardOf({ id: 'SCRN-001', type: 'SCRN', title: 'Home' });

    expect(linesOf(screenMapDiagram([bare]))).toEqual(['flowchart LR', '  s1["Home"]']);
  });

  it('RF-261 cards that are not screens are left out', () => {
    const cards = [cardOf({ id: 'FEAT-001', type: 'FEAT', title: 'x' }), ...demoScreens()];

    expect(screenMapDiagram(cards)).toBe(screenMapDiagram(demoScreens()));
  });

  it('RF-261 a repository without screens gives a map with no node', () => {
    expect(screenMapDiagram([])).toBe('flowchart LR\n');
  });

  it('RF-508 node ids are generated, never taken from the card ids or routes', () => {
    const screens = [screenCard('end', 'subgraph', ['click'])];

    expect(linesOf(screenMapDiagram(screens))).toEqual([
      'flowchart LR',
      '  s1["subgraph"]',
      '  s2["click"]',
      '  s1 --> s2',
    ]);
  });

  it('RF-508 a hostile route stays inside its node', () => {
    const screens = [screenCard('SCRN-001', '"]\n  s1 --> s1\n  click s1 "javascript:x', [])];

    expect(linesOf(screenMapDiagram(screens))).toHaveLength(2);
  });
});
